import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireForms Release Notes — 2023","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireForms/aireforms-2023.md","filePath":"aireblock-releases/AireForms/aireforms-2023.md","lastUpdated":1786968286000}`),a={name:`aireblock-releases/AireForms/aireforms-2023.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireforms-release-notes-—-2023" tabindex="-1"><span class="fsc-product"><img src="/aireforms-icon.png"> AireForms Release Notes — 2023</span> <a class="header-anchor" href="#aireforms-release-notes-—-2023" aria-label="Permalink to “AireForms Release Notes — 2023”">​</a></h1><p>This page contains the AireForms releases published during 2023.</p><h2 id="version-8-1-8-—-designer-tables-aireflow-event-fix" tabindex="-1">Version 8.1.8 — Designer Tables &amp; AireFlow Event Fix <a class="header-anchor" href="#version-8-1-8-—-designer-tables-aireflow-event-fix" aria-label="Permalink to “Version 8.1.8 — Designer Tables &amp; AireFlow Event Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 14, 2023</p></blockquote><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Added a new table structure for displaying building blocks, forms and reference data in the designer</li></ul><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where the previously submitted flag was incorrectly calculated when sending an event to AireFlow via the event bus</li></ul><h2 id="version-8-0-0-—-user-identifier-support" tabindex="-1">Version 8.0.0 — User Identifier Support <a class="header-anchor" href="#version-8-0-0-—-user-identifier-support" aria-label="Permalink to “Version 8.0.0 — User Identifier Support”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 10, 2023</p></blockquote><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>User identifier type is now returned on persisted forms API calls</li></ul><h3 id="⚠️-breaking-changes" tabindex="-1">⚠️ Breaking Changes <a class="header-anchor" href="#⚠️-breaking-changes" aria-label="Permalink to “⚠️ Breaking Changes”">​</a></h3><ul><li>Forms.Api package updated to 4.0.0, including terminology changes and user identifier type support</li></ul><h2 id="version-7-9-0-—-persisted-form-context" tabindex="-1">Version 7.9.0 — Persisted Form Context <a class="header-anchor" href="#version-7-9-0-—-persisted-form-context" aria-label="Permalink to “Version 7.9.0 — Persisted Form Context”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 20, 2023</p></blockquote><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Include the instance GUID in the form context of persisted forms</li></ul><h2 id="version-7-8-0-—-form-author-support-react-18" tabindex="-1">Version 7.8.0 — Form Author Support &amp; React 18 <a class="header-anchor" href="#version-7-8-0-—-form-author-support-react-18" aria-label="Permalink to “Version 7.8.0 — Form Author Support &amp; React 18”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 10, 2023</p></blockquote><h3 id="⚠️-breaking-changes-1" tabindex="-1">⚠️ Breaking Changes <a class="header-anchor" href="#⚠️-breaking-changes-1" aria-label="Permalink to “⚠️ Breaking Changes”">​</a></h3><ul><li>Forms Persistence package updated to 3.0.0 to support form author information</li></ul><h3 id="⚡-improvements-2" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-2" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Upgraded React from 17 to 18</li><li>Added initial support for recording the form author as either a subject or user</li><li>Include the instance GUID in the form context of persisted forms</li></ul><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where the server-side calculation control fired requests in read view</li><li>Fixed an issue where the <code>templateId</code> attribute was incorrectly removed from form data</li></ul><h2 id="version-7-7-0-—-right-to-left-languages-event-bus" tabindex="-1">Version 7.7.0 — Right-to-Left Languages &amp; Event Bus <a class="header-anchor" href="#version-7-7-0-—-right-to-left-languages-event-bus" aria-label="Permalink to “Version 7.7.0 — Right-to-Left Languages &amp; Event Bus”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 25, 2023</p></blockquote><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added initial support for right-to-left languages in forms and PDFs</li><li>Added support for automatic translation of designer-specified text fields and text areas in Single Pass forms</li><li>Added initial support for publishing events across the AireSuite event bus</li></ul><h3 id="⚡-improvements-3" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-3" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Changed the styling engine to support right-to-left languages</li></ul><h3 id="🐞-bug-fixes-2" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-2" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed numerous issues with image-based controls when used within a repeat</li></ul><h3 id="🔧-maintenance" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Local logins are no longer supported for the designer environment; all logins must use AireIdentity</li></ul><h2 id="version-7-6-5-—-lazy-select-data-source-fix" tabindex="-1">Version 7.6.5 — Lazy Select Data Source Fix <a class="header-anchor" href="#version-7-6-5-—-lazy-select-data-source-fix" aria-label="Permalink to “Version 7.6.5 — Lazy Select Data Source Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 16, 2023</p></blockquote><h3 id="🐞-bug-fixes-3" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-3" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where lazy selects did not respect the data source specified in the designer</li></ul><h2 id="version-7-6-4-—-select-initial-value-fix" tabindex="-1">Version 7.6.4 — Select Initial Value Fix <a class="header-anchor" href="#version-7-6-4-—-select-initial-value-fix" aria-label="Permalink to “Version 7.6.4 — Select Initial Value Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 4, 2023</p></blockquote><h3 id="🐞-bug-fixes-4" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-4" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where a select control with an initial value did not correctly create a <code>displayName</code> attribute</li></ul><h2 id="version-7-6-3-—-designer-performance-rollback" tabindex="-1">Version 7.6.3 — Designer Performance Rollback <a class="header-anchor" href="#version-7-6-3-—-designer-performance-rollback" aria-label="Permalink to “Version 7.6.3 — Designer Performance Rollback”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 15, 2023</p></blockquote><h3 id="🐞-bug-fixes-5" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-5" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Rolled back part of the designer performance improvements due to issues in live environments</li></ul><h2 id="version-7-6-2-—-launch-pod-styling-fixes" tabindex="-1">Version 7.6.2 — Launch &amp; POD Styling Fixes <a class="header-anchor" href="#version-7-6-2-—-launch-pod-styling-fixes" aria-label="Permalink to “Version 7.6.2 — Launch &amp; POD Styling Fixes”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 14, 2023</p></blockquote><h3 id="🐞-bug-fixes-6" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-6" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed styling issues on the launch and POD pages following the control library upgrade</li></ul><h2 id="version-7-6-1-—-operational-service-health-check-fix" tabindex="-1">Version 7.6.1 — Operational Service Health Check Fix <a class="header-anchor" href="#version-7-6-1-—-operational-service-health-check-fix" aria-label="Permalink to “Version 7.6.1 — Operational Service Health Check Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 14, 2023</p></blockquote><h3 id="🐞-bug-fixes-7" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-7" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where a health check library upgrade created too many PostgreSQL connections in the operational service</li></ul><h2 id="version-7-6-0-—-building-block-rollback-designer-performance" tabindex="-1">Version 7.6.0 — Building Block Rollback &amp; Designer Performance <a class="header-anchor" href="#version-7-6-0-—-building-block-rollback-designer-performance" aria-label="Permalink to “Version 7.6.0 — Building Block Rollback &amp; Designer Performance”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 14, 2023</p></blockquote><h3 id="✨-new-features-2" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-2" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added the ability to roll back a building block in the designer to the last imported version</li></ul><h3 id="⚡-improvements-4" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-4" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved visual feedback on the lazy select control when used with <code>Load initial reference data</code></li><li>Improved loading time when creating and editing forms</li></ul><h3 id="🐞-bug-fixes-8" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-8" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where images were stored in the form definition multiple times</li><li>Fixed an issue where omit from submission did not work when a control was inside a repeat</li></ul><h3 id="🔧-maintenance-1" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance-1" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Upgraded the MUI control library from v4 to v5</li><li>Upgraded from System.Data.SqlClient to Microsoft.Data.SqlClient</li></ul><h2 id="version-7-5-0-—-partial-date-control" tabindex="-1">Version 7.5.0 — Partial Date Control <a class="header-anchor" href="#version-7-5-0-—-partial-date-control" aria-label="Permalink to “Version 7.5.0 — Partial Date Control”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 20, 2023</p></blockquote><h3 id="✨-new-features-3" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-3" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added a new Partial Date control</li><li>Added a <code>form-keep-alive</code> client-side message triggered every five minutes when there has been user interaction with the form</li></ul><h3 id="⚡-improvements-5" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-5" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Added first-class support for column spans in the building block designer</li><li>Single Pass forms can now include a custom submission error message</li><li>Persisted forms now support the optional <code>internal-previously-submitted</code> value, depending on the persistence implementation</li></ul><h2 id="version-7-4-1-—-ingress-health-checks" tabindex="-1">Version 7.4.1 — Ingress Health Checks <a class="header-anchor" href="#version-7-4-1-—-ingress-health-checks" aria-label="Permalink to “Version 7.4.1 — Ingress Health Checks”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 5, 2023</p></blockquote><h3 id="🐞-bug-fixes-9" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-9" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Added health checks to the ingress Helm chart</li></ul><h2 id="version-7-4-0-—-translation-designer-improvements" tabindex="-1">Version 7.4.0 — Translation &amp; Designer Improvements <a class="header-anchor" href="#version-7-4-0-—-translation-designer-improvements" aria-label="Permalink to “Version 7.4.0 — Translation &amp; Designer Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 30, 2023</p></blockquote><h3 id="✨-new-features-4" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-4" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for moving a grid up and down in the building block designer</li><li>Added translation support for PDF rendering of structured controls</li><li>Added the ability to view building blocks from the building blocks screen as Single Pass or clinician-facing</li><li>Added translation support for structured controls</li><li>Added the <code>nf:other-value()</code> custom XPath function to return an &quot;other&quot; value</li></ul><h3 id="⚡-improvements-6" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-6" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Dynamic Dropdown Item, Label and Value XPath settings are now only shown for the AireForms source</li><li>Improved handling of failed building block saves</li><li>Improved operational service database connection handling</li><li>Improved language code detection and loading</li><li>Updated the Forms Persistence plugin to 2.3.1</li></ul><h3 id="🐞-bug-fixes-10" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-10" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Pre-population now supports correlation ID fallback to the instance GUID when a correlation ID is not specified</li></ul><h2 id="version-7-3-3-—-designer-keyboard-shortcuts" tabindex="-1">Version 7.3.3 — Designer Keyboard Shortcuts <a class="header-anchor" href="#version-7-3-3-—-designer-keyboard-shortcuts" aria-label="Permalink to “Version 7.3.3 — Designer Keyboard Shortcuts”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 14, 2023</p></blockquote><h3 id="🔧-maintenance-2" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance-2" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Removed cut, copy and paste keyboard shortcuts from the designer due to unforeseen issues</li></ul><h2 id="version-7-3-2-—-cut-copy-paste-fix" tabindex="-1">Version 7.3.2 — Cut, Copy &amp; Paste Fix <a class="header-anchor" href="#version-7-3-2-—-cut-copy-paste-fix" aria-label="Permalink to “Version 7.3.2 — Cut, Copy &amp; Paste Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 12, 2023</p></blockquote><h3 id="🐞-bug-fixes-11" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-11" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Improved handling of cut, copy and paste keyboard shortcuts in the designer</li></ul><h2 id="version-7-3-1-—-logging-improvements" tabindex="-1">Version 7.3.1 — Logging Improvements <a class="header-anchor" href="#version-7-3-1-—-logging-improvements" aria-label="Permalink to “Version 7.3.1 — Logging Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 9, 2023</p></blockquote><h3 id="⚡-improvements-7" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-7" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Reduced additional unnecessary log output</li></ul><h2 id="version-7-3-0-—-grid-splitting-server-side-calculations" tabindex="-1">Version 7.3.0 — Grid Splitting &amp; Server-Side Calculations <a class="header-anchor" href="#version-7-3-0-—-grid-splitting-server-side-calculations" aria-label="Permalink to “Version 7.3.0 — Grid Splitting &amp; Server-Side Calculations”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 6, 2023</p></blockquote><h3 id="✨-new-features-5" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-5" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added the ability to split a grid in the building block designer</li><li>Added support for copy, cut and paste of controls using native keyboard shortcuts</li><li>Added support for displaying an HTML response from a server-side calculation</li><li>Added an option to immediately trigger a server-side calculation</li></ul><h3 id="⚡-improvements-8" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-8" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Added an additional security header</li><li>Improved non-highlighted explanatory text styling for accessibility</li></ul><h3 id="🐞-bug-fixes-12" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-12" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where server-side calculation values did not display in PDFs</li><li>Fixed an error when pressing Backspace in an empty lazy select control</li></ul><h2 id="version-7-2-0-—-translation-notifications-annotated-images" tabindex="-1">Version 7.2.0 — Translation Notifications &amp; Annotated Images <a class="header-anchor" href="#version-7-2-0-—-translation-notifications-annotated-images" aria-label="Permalink to “Version 7.2.0 — Translation Notifications &amp; Annotated Images”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 24, 2023</p></blockquote><h3 id="✨-new-features-6" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-6" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added a notification when editing reference data with translations to improve visibility of translation-related changes</li></ul><h3 id="⚡-improvements-9" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-9" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Refactored copy-value components for design payloads and images in the debug tools</li><li>Removed support for combining initial and calculated values on controls that generate images or videos</li><li>Refined the functionality available through the Advanced Annotated Image control</li></ul><h3 id="🐞-bug-fixes-13" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-13" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where AireGlu providers did not use a versioned endpoint URL</li></ul><h2 id="version-7-1-1-—-browser-image-compression-fix" tabindex="-1">Version 7.1.1 — Browser Image Compression Fix <a class="header-anchor" href="#version-7-1-1-—-browser-image-compression-fix" aria-label="Permalink to “Version 7.1.1 — Browser Image Compression Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 10, 2023</p></blockquote><h3 id="🐞-bug-fixes-14" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-14" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where the browser image compression script failed to load</li></ul><h2 id="version-7-1-0-—-advanced-annotated-image-control" tabindex="-1">Version 7.1.0 — Advanced Annotated Image Control <a class="header-anchor" href="#version-7-1-0-—-advanced-annotated-image-control" aria-label="Permalink to “Version 7.1.0 — Advanced Annotated Image Control”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 9, 2023</p></blockquote><h3 id="✨-new-features-7" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-7" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added a new Advanced Annotated Image control supporting drawing and text annotations</li></ul><h3 id="⚡-improvements-10" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-10" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Increased error-handling coverage</li></ul><h3 id="🐞-bug-fixes-15" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-15" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where the clinician forms mobile banner was missing the secondary identifier</li></ul><h2 id="version-7-0-1-—-nhs-mail-hotfix" tabindex="-1">Version 7.0.1 — NHS Mail Hotfix <a class="header-anchor" href="#version-7-0-1-—-nhs-mail-hotfix" aria-label="Permalink to “Version 7.0.1 — NHS Mail Hotfix”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 30, 2023</p></blockquote><h3 id="🐞-bug-fixes-16" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-16" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Moved NHS Mail delivery to SMTP Basic Authentication after NHS Mail removed Basic Authentication via Exchange</li></ul><h3 id="⚠️-notice" tabindex="-1">⚠️ Notice <a class="header-anchor" href="#⚠️-notice" aria-label="Permalink to “⚠️ Notice”">​</a></h3><ul><li>SMTP Basic Authentication was subsequently removed by NHS Mail; work was required through DCB159 to support sending from an approved AireLogic email address</li></ul><h2 id="version-7-0-0-—-security-browser-support-changes" tabindex="-1">Version 7.0.0 — Security &amp; Browser Support Changes <a class="header-anchor" href="#version-7-0-0-—-security-browser-support-changes" aria-label="Permalink to “Version 7.0.0 — Security &amp; Browser Support Changes”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 25, 2023</p></blockquote><h3 id="⚠️-breaking-changes-2" tabindex="-1">⚠️ Breaking Changes <a class="header-anchor" href="#⚠️-breaking-changes-2" aria-label="Permalink to “⚠️ Breaking Changes”">​</a></h3><ul><li>Docker containers now run as non-root, improving security but requiring permission changes for mounted volumes</li><li>Removed support for Internet Explorer 11</li></ul><h2 id="version-6-5-0-—-aireglu-server-side-calculations" tabindex="-1">Version 6.5.0 — AireGlu Server-Side Calculations <a class="header-anchor" href="#version-6-5-0-—-aireglu-server-side-calculations" aria-label="Permalink to “Version 6.5.0 — AireGlu Server-Side Calculations”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 20, 2023</p></blockquote><h3 id="✨-new-features-8" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-8" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added first-class support for AireGlu as a source for the Server-Side Calculation control</li></ul><h3 id="⚡-improvements-11" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-11" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved the designer login splash screen when using AireIdentity</li><li>Expanded framework-level translations to include Polish, Romanian and Slovakian</li></ul><h3 id="🐞-bug-fixes-17" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-17" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where forms failed to load in Internet Explorer 11 from version 6.3.0</li></ul><h2 id="version-6-4-1-—-legacy-safari-fix" tabindex="-1">Version 6.4.1 — Legacy Safari Fix <a class="header-anchor" href="#version-6-4-1-—-legacy-safari-fix" aria-label="Permalink to “Version 6.4.1 — Legacy Safari Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 13, 2023</p></blockquote><h3 id="🐞-bug-fixes-18" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-18" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue with forms loaded on older iOS and macOS Safari versions</li></ul><h2 id="version-6-4-0-—-designer-xsd-fixes" tabindex="-1">Version 6.4.0 — Designer &amp; XSD Fixes <a class="header-anchor" href="#version-6-4-0-—-designer-xsd-fixes" aria-label="Permalink to “Version 6.4.0 — Designer &amp; XSD Fixes”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 24, 2023</p></blockquote><h3 id="🐞-bug-fixes-19" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-19" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where users with only a publish role were still redirected to the building blocks page after login</li><li>Corrected XSD generation for the Annotation control</li></ul><h2 id="version-6-3-1-—-management-oidc-fix" tabindex="-1">Version 6.3.1 — Management OIDC Fix <a class="header-anchor" href="#version-6-3-1-—-management-oidc-fix" aria-label="Permalink to “Version 6.3.1 — Management OIDC Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 9, 2023</p></blockquote><h3 id="🐞-bug-fixes-20" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-20" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed management OIDC issues</li></ul><h2 id="version-6-3-0-—-wizard-navigation-improvements" tabindex="-1">Version 6.3.0 — Wizard Navigation Improvements <a class="header-anchor" href="#version-6-3-0-—-wizard-navigation-improvements" aria-label="Permalink to “Version 6.3.0 — Wizard Navigation Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 7, 2023</p></blockquote><h3 id="⚡-improvements-12" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-12" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Optimised padding on Wizard navigation buttons</li></ul><h3 id="🐞-bug-fixes-21" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-21" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where selecting Preview in the form builder resulted in errors</li></ul><h2 id="version-6-2-0-—-aireglu-reference-data-provider" tabindex="-1">Version 6.2.0 — AireGlu Reference Data Provider <a class="header-anchor" href="#version-6-2-0-—-aireglu-reference-data-provider" aria-label="Permalink to “Version 6.2.0 — AireGlu Reference Data Provider”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 23, 2023</p></blockquote><h3 id="✨-new-features-9" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-9" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added reference data source support in the designer</li><li>Added first-class support for AireGlu as a reference data provider</li><li>Added support for default values in certain controls within repeats</li></ul><h3 id="🐞-bug-fixes-22" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-22" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed a 404 when selecting a page navigation link in a multi-page clinician form</li><li>Fixed Single Pass submission logging so it is only triggered after successful submission</li><li>Prevented users from submitting a form while server-side calculation requests are still in flight</li></ul><h2 id="version-6-1-0-—-form-context-accessibility" tabindex="-1">Version 6.1.0 — Form Context &amp; Accessibility <a class="header-anchor" href="#version-6-1-0-—-form-context-accessibility" aria-label="Permalink to “Version 6.1.0 — Form Context &amp; Accessibility”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 31, 2023</p></blockquote><h3 id="✨-new-features-10" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-10" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added the ability to specify form context in the form designer</li><li>Added support for alt text on static images for accessibility</li><li>Added support for default values for certain controls in repeats</li></ul><h3 id="⚡-improvements-13" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-13" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Added additional health checks</li><li>Auto-generated key suggestions are now lowercase</li></ul><h3 id="🐞-bug-fixes-23" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-23" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed mobile Wizard view showing three steps instead of only the current step</li><li>Fixed a display issue with the repeat delete-iteration icon</li><li>Fixed an issue where the Formatted Text Area control display type was not correctly rehydrated in the new designer</li></ul><h2 id="version-6-0-0-—-schema-build-toolchain-changes" tabindex="-1">Version 6.0.0 — Schema &amp; Build Toolchain Changes <a class="header-anchor" href="#version-6-0-0-—-schema-build-toolchain-changes" aria-label="Permalink to “Version 6.0.0 — Schema &amp; Build Toolchain Changes”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 6, 2023</p></blockquote><h3 id="⚠️-major-changes" tabindex="-1">⚠️ Major Changes <a class="header-anchor" href="#⚠️-major-changes" aria-label="Permalink to “⚠️ Major Changes”">​</a></h3><ul><li>Introduced a large schema change to resolve timing issues</li><li>Up-versioned multiple packages to new major versions, including a new JavaScript build toolchain</li></ul><h3 id="✨-new-features-11" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-11" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added write-back and Git commit support in the operational service</li><li>Lazy Select now supports <code>With Other</code></li></ul><h3 id="⚡-improvements-14" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-14" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved Lazy Select error handling</li><li>Default values configured in Orbeon are migrated to the <code>Initial value</code> calculation when opened in the new designer, where an initial-value calculation does not already exist</li></ul><h3 id="🐞-bug-fixes-24" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-24" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where the YouTube control video URL was not rehydrated in the new designer</li></ul>`,184)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};